mapper.select:
select

from t_structured_message
where 1 = 1

    and id=#{structuredMessageEntity.id}


    and project_id=#{structuredMessageEntity.projectId}


AND (
/* 租户可见性：domainId匹配 */
visibility = 'tenant' AND domain_id = #{structuredMessageEntity.domainId}
OR
/* 空间可见性：workspaceId匹配且在该空间授权 */
visibility = 'workspace' AND workspace_id = #{structuredMessageEntity.workspaceId}
OR
/* 个人可见性：userid匹配 */
visibility = 'personal' AND creator_id = #{structuredMessageEntity.userId}
)


    and name like concat('%', #{structuredMessageEntity.name,jdbcType=VARCHAR}, '%') escape '!'


    and category=#{structuredMessageEntity.category}


    and status=#{structuredMessageEntity.status}


    and import_method=#{structuredMessageEntity.importMethod}


    and visibility=#{structuredMessageEntity.visibility}


    and creator_id=#{structuredMessageEntity.creatorId}


    and created_on=#{structuredMessageEntity.createdOn}


    and updater_id=#{structuredMessageEntity.updaterId}


    and updated_on=#{structuredMessageEntity.updatedOn}

order by updated_on


        asc


        desc

select

from t_structured_message
where id in

    #{deploymentId,jdbcType=VARCHAR}

and (
/* 租户可见性：domainId匹配 */
visibility = 'tenant' AND domain_id = #{domainId}
or
/* 空间可见性：workspaceId匹配且在该空间授权 */
visibility = 'workspace' AND workspace_id = #{workspaceId}
or
/* 个人可见性：userid匹配 */
visibility = 'personal' AND creator_id = #{userId}
)
order by updated_on desc
